import{_ as o,r as a,o as d,c as l,e as t,a as r,s as p}from"./chunks/framework.CXcwiNg-.js";const h=JSON.parse('{"title":"Поле Media Finder - October CMS - 3.x","titleTemplate":false,"description":"Виджет формы","frontmatter":{"subtitle":"Виджет формы","shortname":"Media Finder"},"headers":[{"level":2,"title":"Выбор нескольких элементов","slug":"выбор-нескольких-элементов","link":"#выбор-нескольких-элементов","children":[]}],"relativePath":"3.x/ru/element/form/widget-mediafinder.md","filePath":"3.x/ru/element/form/widget-mediafinder.md"}'),c={name:"3.x/ru/element/form/widget-mediafinder.md"};function i(u,e,m,g,k,f){const n=a("pre-heading"),s=a("post-heading");return d(),l("div",null,[t(n),e[0]||(e[0]=r("h1",null,"Поле Media Finder",-1)),t(s),e[1]||(e[1]=p(`<p><code>mediafinder</code> — рендерит поле для выбора элемента из библиотеки медиа-менеджера. При раскрытии поля отображается медиа-менеджер для поиска файла. Результат выбора — строка с относительным путём к файлу.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">whitepaper_file</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Whitepaper PDF
    <span class="token key atrule">type</span><span class="token punctuation">:</span> mediafinder
</code></pre></div><p>Поддерживаются и обычно используются следующие <a href="./../form-fields.html">свойства поля</a>.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>имя при отображении поля формы пользователю.</td></tr><tr><td><strong>default</strong></td><td>значение по умолчанию (строка), необязательно.</td></tr><tr><td><strong>comment</strong></td><td>пояснительный комментарий под полем.</td></tr><tr><td><strong>mode</strong></td><td>ожидаемый тип файла: <code>file</code>, <code>folder</code> или <code>image</code>. По умолчанию: <code>file</code>.</td></tr><tr><td><strong>imageWidth</strong></td><td>при использовании типа image превью изображения будет отображаться с этой шириной, необязательно.</td></tr><tr><td><strong>imageHeight</strong></td><td>при использовании типа image превью изображения будет отображаться с этой высотой, необязательно.</td></tr><tr><td><strong>maxItems</strong></td><td>максимальное количество элементов, которые можно выбрать.</td></tr><tr><td><strong>thumbOptions</strong></td><td>дополнительные <a href="./../../extend/services/resizer.html">опции масштабирования</a> для генерации миниатюры, или <code>false</code> для отключения генерации миниатюр.</td></tr></tbody></table></div><p>Установите <code>mode</code> в <strong>image</strong> для отображения превью выбранного изображения.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">background_image</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Background Image
    <span class="token key atrule">type</span><span class="token punctuation">:</span> mediafinder
    <span class="token key atrule">mode</span><span class="token punctuation">:</span> image
</code></pre></div><p>Вы можете установить <code>mode</code> в <strong>folder</strong> для выбора только пути к медиа-папке.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">media_folder</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Media Folder
    <span class="token key atrule">type</span><span class="token punctuation">:</span> mediafinder
    <span class="token key atrule">mode</span><span class="token punctuation">:</span> folder
</code></pre></div><div class="custom-block tip"><p>В отличие от <a href="./widget-fileupload.html">виджета формы File Upload</a>, виджет формы Media Finder хранит данные в виде строки, представляющей путь к медиа-файлам, выбранным в медиа-библиотеке. Он должен быть связан с обычным атрибутом вашей модели.</p></div><h2 id="выбор-нескольких-элементов"><a href="#выбор-нескольких-элементов" class="header-anchor">#</a> Выбор нескольких элементов</h2><p>Media Finder автоматически определяет, можно ли выбрать несколько элементов, на основе <a href="./../../extend/system/models.html">атрибута jsonable</a> в модели, что является обязательным условием для хранения нескольких элементов.</p><p>Вы можете ограничить количество выбираемых элементов с помощью свойства <code>maxItems</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">media_gallery</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Image
    <span class="token key atrule">type</span><span class="token punctuation">:</span> mediafinder
    <span class="token key atrule">mode</span><span class="token punctuation">:</span> image
    <span class="token key atrule">maxItems</span><span class="token punctuation">:</span> <span class="token number">10</span>
</code></pre></div>`,13))])}const _=o(c,[["render",i]]);export{h as __pageData,_ as default};
